 'sn_now_record_form.u_SupportedFileTypesForAttachmentPreview',
 'sn_agent_workspace.preview_attachment.disabled',
 'glide.attachment.extensions',
 'com.glide.attachment.max_size',

 // ACTIVITY + COMPOSE
 'glide.activity.api_version',
 'glide.sys.language',
 'glide.ui.activity.email.use_display',
 'glide.ui.activity.filter_persistence_level',
 'glide.ui.activity.sort_persistence_level',
 'glide.ui.journal.enable_mentions',
