 'glide.ui.journal.use_html',
 'glide.ui.journal.html.toolbar',
 'glide.ui.journal.html.plugins'
];

const CONDITION = `name=` + REQUIRED_SYS_PROPERTIES.join('^ORname=');

const SYS_PROPS_QUERY = `
{
 GlideRecord_Query {
 sys_properties(queryConditions:"${CONDITION}") {
 _results {
 name {
