","import React, { useState } from "react";
import { Button } from "@servicenow/react-components/Button";

interface RecordProductionFormProps {
 sysId: string;
 maxQty: number;
 onSuccess: (msg: string) => void;
 onError: (msg: string) => void;
 onRefresh: () => void;
}

export default function RecordProductionForm({
 sysId, maxQty, onSuccess, onError, onRefresh,
}: RecordProductionFormProps) {
 const [produced, setProduced] = useState("");
 const [rejected, setRejected] = useState("");
 const [notes, setNotes] = useState("");
 const [submitting, setSubmitting] = useState(false);

 const prodVal = parseFloat(produced) || 0;
 const rejVal = parseFloat(rejected) || 0;
 const total = prodVal + rejVal;

 const clientValid =
 produced !== "" && prodVal >= 0 && rejVal >= 0 && total > 0 && total <= maxQty;

 const handleSubmit = async () => {
 if (!clientValid) return;
 setSubmitting(true);
 try {
 const res = await fetch(
 "/api/x_2056099_indust_0/operator_api/record-production",
 {
 method: "POST",
 headers: {
 "Content-Type": "application/json",
 "X-UserToken": (window as any).g_ck || "",
 },
 body: JSON.stringify({
 sys_id: sysId,
 produced_quantity: prodVal,
 rejected_quantity: rejVal,
 notes: notes,
 }),
 }
 );
 const json = await res.json();
 const result = json.result || {};
 if (result.success) {
 onSuccess(result.message);
 setProduced("");
 setRejected("");
 setNotes("");
 onRefresh();
 } else {
 onError(result.error || "Failed to record production");
 }
 } catch (e: any) {
 onError(e.message || "Network error");
 } finally {
 setSubmitting(false);
 }
 };

 return (
 <div className="record-form">
 <div className="record-form-title">Record Production</div>
 <div className="record-form-hint">
 Max recordable: {maxQty}
 </div>
 <div className="record-form-row">
 <label className="record-form-label">
 Produced Qty *
 <input
 className="record-form-input"
 type="number"
 min="0"
 step="1"
 value={produced}
 onChange={(e) => setProduced(e.target.value)}
 placeholder="0"
 />
 </label>
 <label className="record-form-label">
 Rejected Qty
 <input
 className="record-form-input"
 type="number"
 min="0"
 step="1"
 value={rejected}
 onChange={(e) => setRejected(e.target.value)}
 placeholder="0"
 />
 </label>
 </div>
 {total > maxQty && (
 <div className="exec-message exec-error" style={{ marginTop: 0, marginBottom: "0.75rem" }}>
 Total ({total}) exceeds remaining capacity ({maxQty})
 </div>
 )}
 <label className="record-form-label record-form-full">
 Notes (optional)
 <textarea
 className="record-form-textarea"
 value={notes}
 onChange={(e) => setNotes(e.target.value)}
 rows={2}
 placeholder="Shift notes, batch info..."
 />
 </label>
 <Button
 variant="primary"
 onClick={handleSubmit}
 disabled={!clientValid || submitting}
 >
 {submitting ? "Saving..." : "✓ Record Production"}
 </Button>
 </div>
 );
}
","import React, { useState } from "react";
import { Button } from "@servicenow/react-components/Button";
import RecordProductionForm from "./RecordProductionForm";

interface OrderData {
 sys_id: string;
 number: string;
 status: string;
 statusDisplay: string;
 finishedProduct: string;
 quantityPlanned: string;
 quantityProduced: string;
 quantityRemaining: string;
 assignedResource: string;
 resourceFeasibility: string;
 plannedStart: string;
 plannedEnd: string;
 actualStart: string;
 actualEnd: string;
 priority: string;
 active: string;
}

interface ExecutionPanelProps {
 order: OrderData;
 onRefresh: () => void;
}

const STARTABLE = ["planned", "material_check", "materials_reserved"];

function statusClass(status: string): string {
 if (status === "in_production") return "exec-status-active";
 if (status === "completed") return "exec-status-completed";
 if (status === "cancelled" || status === "on_hold") return "exec-status-blocked";
 return "exec-status-ready";
}

export default function ExecutionPanel({ order, onRefresh }: ExecutionPanelProps) {
 const [actionLoading, setActionLoading] = useState(false);
 const [message, setMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);
 const [showRecordForm, setShowRecordForm] = useState(false);

 const canStart = STARTABLE.includes(order.status) && order.active === "1";
 const canRecord = order.status === "in_production" && order.active === "1";
 const remaining = parseFloat(order.quantityRemaining) || 0;
 const canComplete = order.status === "in_production" && order.active === "1" && (parseFloat(order.quantityProduced) || 0) > 0;

 const handleStartProduction = async () => {
 setActionLoading(true);
 setMessage(null);
 try {
 const res = await fetch("/api/x_2056099_indust_0/operator_api/start-production", {
 method: "POST",
 headers: {
 "Content-Type": "application/json",
 "X-UserToken": (window as any).g_ck || "",
 },
 body: JSON.stringify({ sys_id: order.sys_id }),
 });
 const json = await res.json();
 const result = json.result || {};
 if (result.success) {
 setMessage({ type: "success", text: result.message || "Production started" });
 onRefresh();
 } else {
 setMessage({ type: "error", text: result.error || "Start production failed" });
 }
 } catch (e: any) {
 setMessage({ type: "error", text: e.message || "Network error" });
 } finally {
 setActionLoading(false);
 }
 };

 const handleCompleteProduction = async () => {
 setActionLoading(true);
 setMessage(null);
 try {
 const res = await fetch("/api/x_2056099_indust_0/operator_api/complete-production", {
 method: "POST",
 headers: {
 "Content-Type": "application/json",
 "X-UserToken": (window as any).g_ck || "",
 },
 body: JSON.stringify({ sys_id: order.sys_id }),
 });
 const json = await res.json();
 const result = json.result || {};
 if (result.success) {
 setMessage({ type: "success", text: result.message || "Production completed" });
 onRefresh();
 } else {
 setMessage({ type: "error", text: result.error || "Complete production failed" });
 }
 } catch (e: any) {
 setMessage({ type: "error", text: e.message || "Network error" });
 } finally {
 setActionLoading(false);
 }
 };

 return (
 <div className="exec-panel">
 <div className="exec-header">
 <span className="exec-order-number">{order.number}</span>
 <span className={`exec-status-badge ${statusClass(order.status)}`}>
 {order.statusDisplay}
 </span>
 </div>

 <div className="exec-fields">
 <Field label="Finished Product" value={order.finishedProduct} />
 <Field label="Priority" value={order.priority} />
 <Field label="Assigned Resource" value={order.assignedResource || "—"} />
 <Field label="Resource Feasibility" value={order.resourceFeasibility || "—"} />
 </div>

 <div className="exec-qty-row">
 <QtyBox label="Planned" value={order.quantityPlanned} />
 <QtyBox label="Produced" value={order.quantityProduced} accent />
 <QtyBox label="Remaining" value={order.quantityRemaining} />
 </div>

 <div className="exec-fields">
 <Field label="Planned Start" value={order.plannedStart || "—"} />
 <Field label="Planned End" value={order.plannedEnd || "—"} />
 <Field label="Actual Start" value={order.actualStart || "—"} />
 <Field label="Actual End" value={order.actualEnd || "—"} />
 </div>

 {message && (
 <div className={`exec-message ${message.type === "success" ? "exec-success" : "exec-error"}`}>
 {message.text}
 </div>
 )}

 <div className="exec-actions">
 {canStart && (
 <Button variant="primary" onClick={handleStartProduction} disabled={actionLoading}>
 {actionLoading ? "Starting..." : "▶ Start Production"}
 </Button>
 )}
 {canRecord && remaining > 0 && !showRecordForm && (
 <Button variant="primary" onClick={() => { setMessage(null); setShowRecordForm(true); }}>
 📝 Record Production
 </Button>
 )}
 {canComplete && !showRecordForm && (
 <Button variant="secondary" onClick={handleCompleteProduction} disabled={actionLoading}>
 {actionLoading ? "Completing..." : "✓ Complete Production"}
 </Button>
 )}
 {canRecord && showRecordForm && (
 <Button variant="secondary" onClick={() => setShowRecordForm(false)}>
 Cancel
 </Button>
 )}
 </div>

 {showRecordForm && canRecord && (
 <RecordProductionForm
 sysId={order.sys_id}
 maxQty={remaining}
 onSuccess={(msg) => { setMessage({ type: "success", text: msg }); setShowRecordForm(false); }}
 onError={(msg) => setMessage({ type: "error", text: msg })}
 onRefresh={onRefresh}
 />
 )}
 </div>
 );
}

function Field({ label, value }: { label: string; value: string }) {
 return (
 <div className="exec-field">
 <span className="exec-field-label">{label}</span>
 <span className="exec-field-value">{value}</span>
 </div>
 );
}

function QtyBox({ label, value, accent }: { label: string; value: string; accent?: boolean }) {
 return (
 <div className={`exec-qty-box ${accent ? "exec-qty-accent" : ""}`}>
 <div className="exec-qty-value">{value || "0"}</div>
 <div className="exec-qty-label">{label}</div>
 </div>
 );
}
","import React, { useState, useEffect, useCallback } from "react";
import { Button } from "@servicenow/react-components/Button";
import ExecutionPanel from "./ExecutionPanel";

interface OrderDetailViewProps {
 orderId: string;
 navigateToView: (view: string, id?: string) => void;
}

interface OrderData {
 sys_id: string;
 number: string;
 status: string;
 statusDisplay: string;
 finishedProduct: string;
 quantityPlanned: string;
 quantityProduced: string;
 quantityRemaining: string;
 assignedResource: string;
 resourceFeasibility: string;
 plannedStart: string;
 plannedEnd: string;
 actualStart: string;
 actualEnd: string;
 priority: string;
 active: string;
}

function mapRecordToOrder(r: any): OrderData {
 const dv = (f: string) => r[f]?.display_value || "";
 const v = (f: string) => r[f]?.value || "";
 return {
 sys_id: v("sys_id"),
 number: dv("number") || v("sys_id"),
 status: v("status"),
 statusDisplay: dv("status"),
 finishedProduct: dv("finished_product"),
 quantityPlanned: v("quantity_planned"),
 quantityProduced: v("quantity_produced"),
 quantityRemaining: v("quantity_remaining"),
 assignedResource: dv("assigned_resource"),
 resourceFeasibility: dv("resource_feasibility_status"),
 plannedStart: dv("planned_start_date"),
 plannedEnd: dv("planned_end_date"),
 actualStart: dv("actual_start_date"),
 actualEnd: dv("actual_end_date"),
 priority: dv("priority"),
 active: v("active"),
 };
}

export default function OrderDetailView({ orderId, navigateToView }: OrderDetailViewProps) {
 const [order, setOrder] = useState<OrderData | null>(null);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState("");

 const fetchOrder = useCallback(() => {
 setLoading(true);
 setError("");
 const url =
 "/api/now/table/x_2056099_indust_0_production_order/" +
 orderId +
 "?sysparm_display_value=all";
 fetch(url, { headers: { "X-UserToken": (window as any).g_ck || "" } })
 .then((res) => {
 if (!res.ok) throw new Error("Failed to load order");
 return res.json();
 })
 .then((json) => setOrder(mapRecordToOrder(json.result)))
 .catch((e) => setError(e.message))
 .finally(() => setLoading(false));
 }, [orderId]);

 useEffect(() => { fetchOrder(); }, [fetchOrder]);

 if (loading) return <div className="loading">Loading order...</div>;
 if (error) return <div className="exec-message exec-error">{error}</div>;
 if (!order) return <div className="exec-message exec-error">Order not found</div>;

 return (
 <div>
 <ExecutionPanel order={order} onRefresh={fetchOrder} />
 <div className="detail-actions">
 <Button variant="secondary" onClick={() => navigateToView("order-materials", orderId)}>
 View Materials
 </Button>
 </div>
 </div>
 );
}
","import React, { useState } from "react";
import { Button } from "@servicenow/react-components/Button";

interface IssueMaterialFormProps {
 materialSysId: string;
 materialName: string;
 remainingQty: number;
 onSuccess: (msg: string) => void;
 onError: (msg: string) => void;
 onClose: () => void;
}

export default function IssueMaterialForm({ materialSysId, materialName, remainingQty, onSuccess, onError, onClose }: IssueMaterialFormProps) {
 const [qty, setQty] = useState<string>("");
 const [loading, setLoading] = useState(false);
 const [message, setMessage] = useState<{ text: string; error: boolean } | null>(null);

 const handleSubmit = async () => {
 const issueQty = parseFloat(qty);
 if (isNaN(issueQty) || issueQty <= 0) { setMessage({ text: "Quantity must be greater than 0", error: true }); return; }
 if (issueQty > remainingQty) { setMessage({ text: `Quantity exceeds remaining (${remainingQty})`, error: true }); return; }
 setLoading(true);
 setMessage(null);
 try {
 const res = await fetch("/api/x_2056099_indust_0/operator_api/issue-material", {
 method: "POST",
 headers: { "Content-Type": "application/json", "X-UserToken": (window as any).g_ck || "" },
 body: JSON.stringify({ production_material_id: materialSysId, issue_quantity: issueQty }),
 });
 const data = await res.json();
 if (data.result?.success) {
 setMessage({ text: data.result.message, error: false });
 onSuccess(data.result.message);
 } else {
 const err = data.result?.error || "Issue failed";
 setMessage({ text: err, error: true });
 onError(err);
 }
 } catch (e: any) {
 const err = e.message || "Network error";
 setMessage({ text: err, error: true });
 onError(err);
 } finally { setLoading(false); }
 };

 return (
