","import React, { useState, useEffect, useCallback } from "react";
import { NowRecordListConnected } from "@servicenow/react-components/NowRecordListConnected";
import IssueMaterialForm from "./IssueMaterialForm";

interface OrderMaterialsViewProps {
 orderId: string;
 navigateToView: (view: string, id?: string) => void;
}

interface MaterialRow {
 sys_id: string;
 material_product: { display_value: string; value: string };
 required_quantity: { display_value: string; value: string };
 issued_quantity: { display_value: string; value: string };
 remaining_quantity: { display_value: string; value: string };
 status: { display_value: string; value: string };
}

export default function OrderMaterialsView({ orderId, navigateToView }: OrderMaterialsViewProps) {
 const [materials, setMaterials] = useState<MaterialRow[]>([]);
 const [selectedMaterial, setSelectedMaterial] = useState<MaterialRow | null>(null);
 const [refreshKey, setRefreshKey] = useState(0);
 const [message, setMessage] = useState<{ text: string; error: boolean } | null>(null);

 const fetchMaterials = useCallback(async () => {
 try {
 const url = `/api/now/table/x_2056099_indust_0_production_material?sysparm_query=production_order=${orderId}&sysparm_display_value=all&sysparm_fields=sys_id,material_product,required_quantity,issued_quantity,remaining_quantity,status`;
 const res = await fetch(url, { headers: { Accept: "application/json", "X-UserToken": (window as any).g_ck || "" } });
 const data = await res.json();
 setMaterials(data.result || []);
 } catch { setMaterials([]); }
 }, [orderId]);

 useEffect(() => { fetchMaterials(); }, [fetchMaterials, refreshKey]);

 const canIssue = (m: MaterialRow) => {
 const rem = parseFloat(m.remaining_quantity?.value) || 0;
 const st = m.status?.value;
 return rem > 0 && st !== "fully_issued" && st !== "cancelled";
 };

 const handleSuccess = (msg: string) => {
 setMessage({ text: msg, error: false });
 setSelectedMaterial(null);
 setRefreshKey((k) => k + 1);
 };

 return (
 <div>
 <NowRecordListConnected
 key={`materials-${orderId}-${refreshKey}`}
 table="x_2056099_indust_0_production_material"
 listTitle="Material Requirements"
 columns="number,material_product,required_quantity,reserved_quantity,issued_quantity,remaining_quantity,status"
 hideHeader={true}
 />
 <div style={{ marginTop: "16px" }}>
 <div className="record-form-title">Issue Materials</div>
 {message && <div className={message.error ? "exec-error" : "exec-message"} style={{ marginBottom: "8px" }}>{message.text}</div>}
 <div style={{ display: "flex", flexWrap: "wrap", gap: "10px", marginTop: "8px" }}>
 {materials.map((m) => {
 const rem = parseFloat(m.remaining_quantity?.value) || 0;
 const active = canIssue(m);
 return (
 <div key={m.sys_id} className="exec-panel" style={{ cursor: active ? "pointer" : "default", opacity: active ? 1 : 0.5, minWidth: "180px", flex: "1 1 180px" }}
 onClick={() => active && setSelectedMaterial(m)}>
 <div className="exec-header">{m.material_product?.display_value || "Material"}</div>
 <div className="exec-fields">
 <div className="exec-field"><span className="exec-field-label">Required</span><span className="exec-field-value">{m.required_quantity?.display_value}</span></div>
 <div className="exec-field"><span className="exec-field-label">Issued</span><span className="exec-field-value">{m.issued_quantity?.display_value}</span></div>
 <div className="exec-field"><span className="exec-field-label">Remaining</span><span className="exec-field-value">{m.remaining_quantity?.display_value}</span></div>
 </div>
 <span className={`exec-status-badge ${active ? "exec-status-active" : "exec-status-completed"}`}>{m.status?.display_value}</span>
 </div>
 );
 })}
 {materials.length === 0 && <div className="record-form-hint">No materials found for this order.</div>}
 </div>
 </div>
 {selectedMaterial && (
 <IssueMaterialForm
 materialSysId={selectedMaterial.sys_id}
 materialName={selectedMaterial.material_product?.display_value || "Material"}
 remainingQty={parseFloat(selectedMaterial.remaining_quantity?.value) || 0}
 onSuccess={handleSuccess}
 onError={(msg) => setMessage({ text: msg, error: true })}
 onClose={() => setSelectedMaterial(null)}
 />
 )}
 </div>
 );
}
