","/* Production Operator Mobile Styles */

.operator-app {
 display: flex;
 flex-direction: column;
 width: 100vw;
 height: 100vh;
 overflow: hidden;
 font-family: var(--now-font-family, system-ui, sans-serif);
 background-color: rgb(var(--now-color_background--secondary, 245, 246, 247));
 color: rgb(var(--now-color_text--primary, 16, 23, 26));
}

.operator-header {
 position: sticky;
 top: 0;
 z-index: 100;
 display: flex;
 align-items: center;
 gap: var(--now-static-space--md, 0.75rem);
 padding: var(--now-static-space--md, 0.75rem) var(--now-static-space--lg, 1rem);
 background-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 color: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
 box-shadow: var(--now-static-drop-shadow--sm);
}

.operator-header .section-title {
 margin: 0;
 font-size: var(--now-static-font-size--lg, 1.25rem);
 font-weight: 600;
 color: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
 flex: 1;
}

.back-link {
 background: none;
 border: none;
 color: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
 font-size: var(--now-static-font-size--md, 1rem);
 cursor: pointer;
 padding: var(--now-static-space--xs, 0.25rem) var(--now-static-space--sm, 0.5rem);
 border-radius: var(--now-actionable--border-radius, 6px);
 margin: 0;
 transition: background-color 100ms linear;
}

.back-link:hover {
 background-color: rgba(255, 255, 255, 0.15);
}

.operator-content {
 flex: 1;
 overflow-y: auto;
 padding: var(--now-static-space--lg, 1rem);
}

.operator-nav {
 position: fixed;
 bottom: 0;
 left: 0;
 right: 0;
 z-index: 100;
 display: flex;
 justify-content: space-around;
 align-items: center;
 padding: var(--now-static-space--sm, 0.5rem) var(--now-static-space--xs, 0.25rem);
 background-color: rgb(var(--now-container--color, 255, 255, 255));
 border-top: 1px solid rgb(var(--now-container--border-color, 207, 213, 215));
 box-shadow: var(--now-static-drop-shadow--sm);
}

/* Summary Grid - Home Dashboard */
.summary-grid {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: var(--now-static-space--lg, 1rem);
 padding: var(--now-static-space--sm, 0.5rem) 0;
}

.summary-card {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 padding: var(--now-static-space--xl, 1.5rem) var(--now-static-space--lg, 1rem);
 background-color: rgb(var(--now-container--color, 255, 255, 255));
 border: 1px solid rgb(var(--now-container-card--border-color, 207, 213, 215));
 border-radius: var(--now-container-card--border-radius, 8px);
 cursor: pointer;
 transition: box-shadow 0.2s ease, transform 0.15s ease;
 text-align: center;
 box-shadow: var(--now-static-drop-shadow--sm);
}

.summary-card:hover {
 box-shadow: var(--now-static-drop-shadow--md);
 transform: translateY(-2px);
}

.summary-card:active {
 transform: translateY(0);
}

.summary-count {
 font-size: 2.25rem;
 font-weight: 700;
 color: rgb(var(--now-color--primary-1, 0, 128, 163));
 line-height: var(--now-static-line-height, 1.25);
}

.summary-label {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 font-weight: 500;
 color: rgb(var(--now-color_text--secondary, 75, 85, 89));
 margin-top: var(--now-static-space--sm, 0.5rem);
}

/* Detail Actions */
.detail-actions {
 display: flex;
 gap: var(--now-static-space--sm, 0.5rem);
 margin-bottom: var(--now-static-space--lg, 1rem);
}

/* Loading State */
.loading {
 display: flex;
 align-items: center;
 justify-content: center;
 height: 200px;
 font-size: var(--now-static-font-size--md, 1rem);
 color: rgb(var(--now-color_text--secondary, 75, 85, 89));
}

/* ─── Execution Panel ──────────────────────────────────────────────── */

.exec-panel {
 background-color: rgb(var(--now-container--color, 255, 255, 255));
 border: 1px solid rgb(var(--now-container-card--border-color, 207, 213, 215));
 border-radius: var(--now-container-card--border-radius, 8px);
 padding: var(--now-static-space--lg, 1rem);
 margin-bottom: var(--now-static-space--lg, 1rem);
 box-shadow: var(--now-static-drop-shadow--sm);
}

.exec-header {
 display: flex;
 justify-content: space-between;
 align-items: center;
 margin-bottom: var(--now-static-space--lg, 1rem);
 padding-bottom: var(--now-static-space--md, 0.75rem);
 border-bottom: 1px solid rgb(var(--now-container--border-color, 207, 213, 215));
}

.exec-order-number {
 font-size: var(--now-static-font-size--lg, 1.25rem);
 font-weight: 700;
 color: rgb(var(--now-color_text--primary, 16, 23, 26));
}

.exec-status-badge {
 display: inline-block;
 padding: var(--now-static-space--xs, 0.25rem) var(--now-static-space--md, 0.75rem);
 border-radius: 12px;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 font-weight: 600;
 text-transform: uppercase;
 letter-spacing: 0.03em;
}

.exec-status-ready {
 background-color: rgb(var(--now-color_surface--brand-2, 227, 243, 255));
 color: rgb(var(--now-color--primary-1, 0, 128, 163));
}

.exec-status-active {
 background-color: rgba(var(--now-indicator--primary_positive--background-color, 62, 134, 0), 0.12);
 color: rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0));
}

.exec-status-completed {
 background-color: rgb(var(--now-color_background--secondary, 245, 246, 247));
 color: rgb(var(--now-color_text--secondary, 75, 85, 89));
}

.exec-status-blocked {
 background-color: rgba(var(--now-indicator--primary_critical--background-color, 229, 34, 57), 0.12);
 color: rgb(var(--now-indicator--primary_critical--background-color, 229, 34, 57));
}

.exec-fields {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: var(--now-static-space--sm, 0.5rem) var(--now-static-space--lg, 1rem);
 margin-bottom: var(--now-static-space--lg, 1rem);
}

.exec-field {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.exec-field-label {
 font-size: 0.6875rem;
 font-weight: 600;
 color: rgb(var(--now-color_text--secondary, 75, 85, 89));
 text-transform: uppercase;
 letter-spacing: 0.05em;
}

.exec-field-value {
 font-size: var(--now-static-font-size--md, 1rem);
 color: rgb(var(--now-color_text--primary, 16, 23, 26));
 word-break: break-word;
}

.exec-qty-row {
 display: flex;
 gap: var(--now-static-space--md, 0.75rem);
 margin-bottom: var(--now-static-space--lg, 1rem);
}

.exec-qty-box {
 flex: 1;
 text-align: center;
 padding: var(--now-static-space--md, 0.75rem) var(--now-static-space--sm, 0.5rem);
 background-color: rgb(var(--now-color_background--secondary, 245, 246, 247));
 border-radius: var(--now-container-card--border-radius, 8px);
 border: 1px solid rgb(var(--now-container--border-color, 207, 213, 215));
}

.exec-qty-accent {
 background-color: rgb(var(--now-color_surface--brand-2, 227, 243, 255));
 border-color: rgb(var(--now-color--primary-1, 0, 128, 163));
}

.exec-qty-value {
 font-size: 1.5rem;
 font-weight: 700;
 color: rgb(var(--now-color_text--primary, 16, 23, 26));
}

.exec-qty-accent .exec-qty-value {
 color: rgb(var(--now-color--primary-1, 0, 128, 163));
}

.exec-qty-label {
 font-size: 0.6875rem;
 font-weight: 600;
 color: rgb(var(--now-color_text--secondary, 75, 85, 89));
 text-transform: uppercase;
 margin-top: 2px;
}

.exec-actions {
 display: flex;
 gap: var(--now-static-space--sm, 0.5rem);
 margin-top: var(--now-static-space--lg, 1rem);
 padding-top: var(--now-static-space--md, 0.75rem);
 border-top: 1px solid rgb(var(--now-container--border-color, 207, 213, 215));
}

.exec-actions > * {
 flex: 1;
}

.exec-message {
 padding: var(--now-static-space--md, 0.75rem) var(--now-static-space--lg, 1rem);
 border-radius: var(--now-container-card--border-radius, 8px);
 font-size: var(--now-static-font-size--md, 1rem);
 font-weight: 500;
 margin-top: var(--now-static-space--md, 0.75rem);
}

.exec-success {
 background-color: rgba(var(--now-indicator--primary_positive--background-color, 62, 134, 0), 0.1);
 color: rgb(var(--now-indicator--primary_positive--background-color, 62, 134, 0));
 border: 1px solid rgba(var(--now-indicator--primary_positive--background-color, 62, 134, 0), 0.4);
}

.exec-error {
 background-color: rgba(var(--now-indicator--primary_critical--background-color, 229, 34, 57), 0.1);
 color: rgb(var(--now-indicator--primary_critical--background-color, 229, 34, 57));
 border: 1px solid rgba(var(--now-indicator--primary_critical--background-color, 229, 34, 57), 0.4);
}

/* ─── Record Production Form ───────────────────────────────────────── */

.record-form {
 margin-top: var(--now-static-space--lg, 1rem);
 padding-top: var(--now-static-space--lg, 1rem);
 border-top: 1px solid rgb(var(--now-container--border-color, 207, 213, 215));
}

.record-form-title {
 font-size: var(--now-static-font-size--lg, 1.25rem);
 font-weight: 700;
 color: rgb(var(--now-color_text--primary, 16, 23, 26));
 margin-bottom: var(--now-static-space--xs, 0.25rem);
}

.record-form-hint {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: rgb(var(--now-color_text--secondary, 75, 85, 89));
 margin-bottom: var(--now-static-space--lg, 1rem);
}

.record-form-row {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: var(--now-static-space--md, 0.75rem);
 margin-bottom: var(--now-static-space--md, 0.75rem);
}

.record-form-label {
 display: flex;
 flex-direction: column;
 gap: var(--now-static-space--xs, 0.25rem);
 font-size: var(--now-static-font-size--sm, 0.75rem);
 font-weight: 600;
 color: rgb(var(--now-color_text--secondary, 75, 85, 89));
}

.record-form-full {
 margin-bottom: var(--now-static-space--lg, 1rem);
}

.record-form-input {
 height: 2.5rem;
 padding: 0 var(--now-static-space--md, 0.75rem);
 border: 1px solid rgb(var(--now-form-control-input--primary--border-color, 115, 127, 132));
 border-radius: var(--now-form-control-input--primary--border-radius, 2px);
 background-color: rgb(var(--now-color_background--primary, 255, 255, 255));
 color: rgb(var(--now-color_text--primary, 16, 23, 26));
 font-size: var(--now-static-font-size--lg, 1.25rem);
 font-weight: 600;
 font-family: var(--now-font-family, system-ui, sans-serif);
 margin: 0;
}

.record-form-input:focus {
 outline: none;
 border-color: rgb(var(--now-form-control-input--primary--border-color--focus, 53, 147, 37));
 box-shadow: inset 0 0 0 1px rgb(var(--now-form-control-input--primary--border-color--focus, 53, 147, 37));
}

.record-form-textarea {
 padding: var(--now-static-space--sm, 0.5rem) var(--now-static-space--md, 0.75rem);
 border: 1px solid rgb(var(--now-form-control-input--primary--border-color, 115, 127, 132));
 border-radius: var(--now-form-control-input--primary--border-radius, 2px);
 background-color: rgb(var(--now-color_background--primary, 255, 255, 255));
 color: rgb(var(--now-color_text--primary, 16, 23, 26));
 font-size: var(--now-static-font-size--md, 1rem);
 font-family: var(--now-font-family, system-ui, sans-serif);
 resize: vertical;
 margin: 0;
}

.record-form-textarea:focus {
 outline: none;
 border-color: rgb(var(--now-form-control-input--primary--border-color--focus, 53, 147, 37));
 box-shadow: inset 0 0 0 1px rgb(var(--now-form-control-input--primary--border-color--focus, 53, 147, 37));
}

/* Mobile-first responsive adjustments */
@media (max-width: 480px) {
 .summary-grid {
 gap: var(--now-static-space--md, 0.75rem);
 }

 .summary-card {
 padding: var(--now-static-space--lg, 1rem) var(--now-static-space--md, 0.75rem);
 }

 .summary-count {
 font-size: 1.75rem;
 }
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React from "react";
