","import React, { useState, useEffect } from "react";
import { getViewFromUrl, navigateToView } from "./utils/navigation";
import NavBar from "./components/NavBar";
import HomeView from "./components/HomeView";
import OrdersView from "./components/OrdersView";
import OrderDetailView from "./components/OrderDetailView";
import OrderMaterialsView from "./components/OrderMaterialsView";
import RequestsView from "./components/RequestsView";
import RequestCreateView from "./components/RequestCreateView";
import ResourcesView from "./components/ResourcesView";
import AlertsView from "./components/AlertsView";
import "./styles.css";

export default function App() {
 const [currentView, setCurrentView] = useState(getViewFromUrl());

 useEffect(() => {
 const onPopState = () => setCurrentView(getViewFromUrl());
 window.addEventListener("popstate", onPopState);
 return () => window.removeEventListener("popstate", onPopState);
 }, []);

 const { view, id } = currentView;

 const renderView = () => {
 switch (view) {
 case "home":
 return <HomeView navigateToView={navigateToView} />;
 case "orders":
 return (
 <OrdersView
 onSelectOrder={(sysId: string) => navigateToView("order-detail", sysId)}
 />
 );
 case "order-detail":
 return <OrderDetailView orderId={id || ""} navigateToView={navigateToView} />;
 case "order-materials":
 return <OrderMaterialsView orderId={id || ""} navigateToView={navigateToView} />;
 case "requests":
 return <RequestsView onNewRequest={() => navigateToView("request-create")} />;
 case "request-create":
 return <RequestCreateView onBack={() => navigateToView("requests")} />;
 case "resources":
 return <ResourcesView />;
 case "alerts":
 return <AlertsView />;
 default:
 return <HomeView navigateToView={navigateToView} />;
 }
 };

 return (
 <div className="operator-app">
 <div className="operator-header">
 {view !== "home" && (
 <button className="back-link" onClick={() => window.history.back()}>
 ← Back
 </button>
 )}
 <h1 className="section-title">Production Operator</h1>
 </div>
 <div className="operator-content">{renderView()}</div>
 {view === "home" && <NavBar navigateToView={navigateToView} />}
 </div>
 );
}
